using System;
using System.Linq;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;

public class Product
{
    public string Id { get; set; } = "";
    public string Attributes { get; set; } = "{}";
}

public class Ctx : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder o) => o.UseInMemoryDatabase("test");
}

public static class JsonHelper
{
    public static bool AttributeEquals(string json, string attributeName, string value)
    {
        using var doc = JsonDocument.Parse(json);
        if (!doc.RootElement.TryGetProperty(attributeName, out var el)) return false;
        var text = el.ValueKind switch
        {
            JsonValueKind.String => el.GetString(),
            JsonValueKind.True => "true",
            JsonValueKind.False => "false",
            JsonValueKind.Number => el.GetRawText(),
            _ => null
        };
        return text == value;
    }
}

class Program
{
    static void Main()
    {
        using var ctx = new Ctx();
        ctx.Products.Add(new Product { Id = "P1", Attributes = "{\"Bauform\":\"In-Ear\",\"Kabellos\":true}" });
        ctx.Products.Add(new Product { Id = "P2", Attributes = "{\"Bauform\":\"Over-Ear\",\"Kabellos\":false}" });
        ctx.SaveChanges();

        try
        {
            var result = ctx.Products
                .Where(p => JsonHelper.AttributeEquals(p.Attributes, "Bauform", "In-Ear"))
                .ToList();
            Console.WriteLine("SUCCESS: matched " + result.Count + " -> " + string.Join(",", result.Select(p => p.Id)));
        }
        catch (Exception ex)
        {
            Console.WriteLine("FAILED: " + ex.GetType().Name + ": " + ex.Message);
        }
    }
}
